import { Component, Prop, h, State, Event, EventEmitter, Method, Listen } from '@stencil/core';

@Component({
  tag: 'std-select',
  styleUrl: 'std-select.css',
  shadow: true
})
export class CustomSelect {
  @Prop() helperText: string;
  @Prop() status = 'default';
  @Prop() icon: string;

  @Prop() label: string;
  @Prop() placeholder: string = '';
  @Prop() selectTitle: string;
  @Prop() labelClasses: string;
  @Prop() readonly: boolean;
  @Prop() classes: string;
  @Prop() multiple: boolean = false;
  @State() isOpen: boolean;
  @Prop({
    mutable: true
  })
  selectedOption: string = '';
  @Prop() disabled: boolean = false;

  @Event() selectionChanged: EventEmitter<string>;
  @Event({
    bubbles: false
  })
  iconClick: EventEmitter;

  selectElement: HTMLButtonElement;
  menuElement: HTMLDivElement;

  toggleDropdown() {
    if (!this.readonly && !this.disabled) {
      this.isOpen = !this.isOpen;
    }
  }

  @Method()
  async handleSelection(option: string) {
    this.isOpen = false;
    this.selectedOption = option;
    this.selectionChanged.emit(option);
  }

  get labelClass() {
    return [this.labelClasses, this.disabled ? 'opacity-20 cursor-not-allowed' : ''].join(' ').trim();
  }

  get buttonClasses() {
    return [
      'inline-flex w-full items-center justify-between p-[6px] px-[11px] text-base rounded-lg',
      this.readonly || this.disabled ? 'bg-dark/[0.06] cursor-not-allowed' : '',
      !this.selectedOption ? 'text-soft font-normal' : ''
    ]
      .join(' ')
      .trim();
  }

  get iconClasses() {
    return ['icon-chevron-down text-alternative text-2xl', this.readonly || this.disabled ? 'text-soft' : ''].join(' ').trim();
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    // Antigua forma de reconcer el target con shadow
    // const target = this.isShadow ? ev.composedPath()[0] : ev.target;

    const path = ev.composedPath();
    if (this.isOpen && !path.includes(this.selectElement)) {
      if (!this.multiple || (this.menuElement && this.multiple && !path.includes(this.menuElement))) {
        this.isOpen = false;
        return;
      }
    }
  }

  render() {
    const statusClasses = {
      default: 'border-border-default hover:border-dark focus:border-alternative focus:ring-alternative',
      success: 'border-border-default hover:border-dark focus:border-alternative focus:ring-alternative',
      error: 'border-error focus:border-error focus:ring-error'
    }[this.status];

    const selectClasses = [
      'relative !h-[46px] css-select w-full bg-white border rounded-lg',
      // this.readonly || this.disabled ? 'border-transparent pointer-events-none' : 'border-border-default',
      this.readonly || this.disabled ? 'border-transparent pointer-events-none' : statusClasses,
      this.classes
    ]
      .join(' ')
      .trim();

      // const iconCloseClasses = [' text-alternative text-2xl',`icon-${this.icon}`, this.readonly || this.disabled ? 'text-soft' : ''].join(' ').trim();

    return (
      <div class="flex flex-col gap-1 w-full">
        {this.label && <p class={this.labelClass}>{this.label}</p>}
        <div class={selectClasses}>
          <button ref={el => (this.selectElement = el)} type="button" class={this.buttonClasses} onClick={() => this.toggleDropdown()}>
            <span class="text-ellipsis whitespace-nowrap overflow-hidden">{this.selectedOption || this.placeholder}</span>
            <i class={this.iconClasses}></i>
            {/* {this.icon && <i class={iconCloseClasses} onClick={e => this.iconClick.emit(e)} />} */}
          </button>
          {this.isOpen && (
            <div class="flex-col left-[-1px] w-[calc(100%+2px)] px-4 bg-white absolute top-[48px] z-10 shadow-modal rounded-md" ref={el => (this.menuElement = el)}>
              <slot />
            </div>
          )}
        </div>
        {this.helperText && <std-helpertext label={this.helperText} status={this.status} disabled={this.disabled} />}
      </div>
    );
  }
}
